mapper.insert:
insert into inspection_plan_equipment (
plan_id,
equipment_id
)
values

    (
    #{planId},
    #{equipmentId}
    )

insert into inspection_plan_schedule (
plan_id,
day_value
)
values

    (
    #{planId},
    #{dayValue}
    )

mapper.select:
select distinct
p.id as plan_id,
p.frequency_type,
p.start_date,
p.end_date
from inspection_plan p
join inspection_plan_equipment pe
on pe.plan_id = p.id
where p.enabled = 1
and p.execution_time = #{executionTime}

and pe.equipment_id in

    #{equipmentId}


and (
p.end_date is null
or p.end_date >= #{startDate}
)


    and p.start_date <= #{endDate}



    and p.id != #{excludePlanId}

mapper.update:
update inspection_plan
set enabled = #{enabled},
    next_generate_at = #{nextGenerateAt}
where id = #{inspectionPlanId}

mapper.select:
select count(*)
from inspection_task
where plan_id = #{inspectionPlanId}

mapper.update:
update inspection_plan
set next_generate_at = #{next}
where id = #{planId}
  and enabled = 1
  and next_generate_at = #{expected}
